/// Whether `file` declares `name` (an interface, type alias, enum, const array or component, possibly
/// namespace-qualified).
fn declares(data: &SourceData, file: &Utf8Path, name: &str) -> bool {
    let key = format!("{file}:{name}");
    data.interfaces.contains_key(&key)
        || data.type_aliases.contains_key(&key)
        || data.enums.contains_key(&key)
        || data.const_arrays.contains_key(&key)
        || data.component_mappings.iter().any(|m| m.component_name == name)
        // A constant declared by its type alone (`declare const Primitive: Primitives`).
        || data.type_aliases.contains_key(&format!("{file}:typeof {name}"))
}

/// The names `(file, name)`'s declaration references, without its own type parameters.
fn declaration_refs(data: &SourceData, file: &Utf8Path, name: &str, out: &mut FxHashSet<CompactString>) {
    let key = format!("{file}:{name}");
    if let Some(iface) = data.interfaces.get(&key) {
        interface_refs(iface, out);
    }
    if let Some(alias) = data.type_aliases.get(&key) {
        alias_refs(alias, out);
    }
    for mapping in data.component_mappings.iter().filter(|m| m.component_name == name) {
        mapping_refs(mapping, out);
    }
    // A reference that omits an argument reads the default (`DOMAttributes<T = FocusableElement>`).
    for default in data.type_param_defaults.get(&key).into_iter().flatten().flatten() {
        type_refs(default, out);
    }
    for params in [data.interface_type_params.get(&key), data.type_alias_params.get(&key)].into_iter().flatten() {
        for param in params {
            out.remove(param.as_str());
        }
    }
        match self.bindings.get(file.as_str()) {
            Some(per_file) => per_file.get(local_name),
            None => self.fallback.as_ref()?.find_import(file, local_name),
        }
    }

    /// The local name of the declaration `file` itself exports as `name` (`export function f`, `export { g as f }`),
    /// whatever kind of declaration it is.
    pub fn local_export(&self, file: &Utf8Path, name: &str) -> Option<String> {
        let Some(exports) = self.re_exports.get(file.as_str()) else {
            return self.fallback.as_ref()?.local_export(file, name);
        };
        exports.iter().find_map(|export| match export {
            LexedExport::LocalDeclaration { name: exported, declared_as, .. } if exported == name => {
                Some(declared_as.clone().unwrap_or_else(|| exported.clone()))
            }
            _ => None,
        })
    }

    /// Walk one step of the re-export chain for `barrel_file`.
    ///
    /// - If a `ReExportNamed` entry matches `exported_name`, returns `Named { .. }`.
    /// - A member of a re-exported namespace (`Menu.Root` where the barrel has `export * as Menu from "./menu"`)
    ///   returns `Named` for the member in the namespace's module.
    /// - If no named match is found but there are `ReExportAll` entries, returns `Wildcards(..)`.
    /// - Returns `None` if the barrel file has no relevant re-exports.
    pub fn resolve_reexport_chain(&self, barrel_file: &Utf8Path, exported_name: &str) -> Option<ReExportStep> {
        let Some(exports) = self.re_exports.get(barrel_file.as_str()) else {
            return self.fallback.as_ref()?.resolve_reexport_chain(barrel_file, exported_name);
        };
}

/// Whether `mapping` re-binds a component the project itself declares under the same name: `const Alert =
/// InternalAlert` where `InternalAlert` is the project's `Alert`, or `const { Option } = Select` where `Select` is a
/// project component and a project component `Option` exists. An alias of a package's component is not one of these.
fn aliases_project_component(mapping: &ComponentMapping, ctx: &ResolutionContext) -> bool {
    if mapping.rule != DetectionRule::ImportedMemberAlias {
        return false;
    }
    let Some(CollectedType::TypeOf(target)) = mapping.props_type_args.first() else { return false };
    let mut ignored = Vec::new();
    let mut project = |name: &str| {
        let (file, canonical) = import::resolve_to_canonical(name, &mapping.file_path, ctx, &mut ignored)?;
        ctx.component_mapping(&file, &canonical).map(|found| found.component_name.clone())
    };
    match target.split_once('.') {
        None => project(target).is_some_and(|declared| declared == mapping.component_name),
        Some((base, _)) => {
            project(base).is_some()
                && ctx.global.component_mappings.iter().any(|other| {
                    other.rule != DetectionRule::ImportedMemberAlias && other.component_name == mapping.component_name
                })
        }
    }
}


