import json, sys

def load(p):
    d = json.load(open(p))
    d.pop("stats", None)
    return d

def walk(a, b, path, out):
    if type(a) != type(b):
        out.append((path, a, b)); return
    if isinstance(a, dict):
        for k in sorted(set(a) | set(b)):
            if k not in a: out.append((path + "/" + k, None, "ADDED")); continue
            if k not in b: out.append((path + "/" + k, "REMOVED", None)); continue
            walk(a[k], b[k], path + "/" + k, out)
    elif isinstance(a, list):
        if len(a) != len(b): out.append((path, "len %d" % len(a), "len %d" % len(b))); return
        for i, (x, y) in enumerate(zip(a, b)): walk(x, y, "%s[%d]" % (path, i), out)
    elif a != b:
        out.append((path, a, b))

a, b = load(sys.argv[1]), load(sys.argv[2])
out = []
walk(a, b, "", out)
print(len(out), "differences; keys:", sorted(a)[:12])
for o in out[:30]:
    print(str(o)[:300])

